package io.knowledgebrain.learning;
import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.mock.web.MockHttpServletRequest;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class ActivityExportIntegrationTest extends EvidenceSessionFixtures {
 ActivityExportController api;
 @BeforeEach void setup(){init();api=new ActivityExportController(ds,"a".repeat(43),new SimpleMeterRegistry());}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest();r.setSecure(true);r.addHeader("Authorization","Bearer "+"a".repeat(43));return r;}
 @Test void recoveryUsesStableHighWatermarkFiveRowPagesAndAllRetainedKinds()throws Exception{var s=session(node);study.progress(space,roadmap,node,actor,0,"IN_PROGRESS",trace);for(var k:List.of("NOTE","CONCEPT","MEDIA"))link(evidence(k),k,s,0);var first=api.page(null,null,request()).getBody();assertEquals(5,first.items().size());assertNotNull(first.nextAfter());var through=first.through();var found=new HashSet<String>();UUID after=null;int count=0;do{var p=api.page(after,through,request()).getBody();assertEquals(through,p.through());for(var e:p.items()){assertTrue(e.eventId().toString().compareTo(through.toString())<=0);var env=io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1.parseFrom(Base64.getDecoder().decode(e.payload()));if(env.getSpaceId().equals(space.toString()))found.add(e.topic());count++;}after=p.nextAfter();assertTrue(count<50000);}while(after!=null);assertEquals(Set.of("learning.roadmap.v1","learning.progress.v1","learning.study-session.v1","learning.evidence.v1","learning.concept-evidence.v1","learning.media-evidence.v1","learning.evidence-session.v1"),found);assertEquals("no-store",api.page(null,through,request()).getHeaders().getCacheControl());}
 @Test void exportRejectsBrowserCookiesMissingKeysAndUnknownParameters(){var r=request();r.addHeader("Cookie","__Host-brain_guest=anything");assertThrows(ResponseStatusException.class,()->api.page(null,null,r));var wrong=request();wrong.removeHeader("Authorization");assertThrows(ResponseStatusException.class,()->api.page(null,null,wrong));var extra=request();extra.addParameter("spaceId",space.toString());assertThrows(ResponseStatusException.class,()->api.page(null,null,extra));}
}
